/* eslint-env node */
/* eslint-disable @typescript-eslint/no-var-requires -- Playwright CLI uses CommonJS. */
const{chromium}=require('playwright');const assert=require('node:assert/strict');
async function main(){const{createServer}=await import('vite');const server=await createServer({server:{host:'127.0.0.1',port:4320,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});try{for(const theme of ['light','dark'])for(const width of [320,390,768,1024,1440]){
 const context=await browser.newContext({viewport:{width,height:960},hasTouch:width<1024,reducedMotion:'reduce'});await context.addInitScript(t=>localStorage.setItem('hisabiq-theme',t),theme);const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:4320/#/app/purchases');
 const initial=await page.evaluate(async()=>{const{availableParties,availableProducts,createPreviewPurchase}=await import('/src/data/erpDemoStore.ts');const{makePurchaseLine}=await import('/src/utils/purchaseCart.ts');const{businessToday}=await import('/src/utils/dateRange.ts');const supplier=availableParties().find(p=>p.roles.includes('Supplier'));const master=availableProducts()[0];const product={...master,altUnit:undefined,serialTracking:'Off',expiry:undefined,warranty:undefined};const line={...makePurchaseLine(product),smallQty:'10',cost:'10',costUnit:product.unit};createPreviewPurchase({id:'pu-source-browser',ref:'PUR-FRONTEND',date:businessToday(),businessDate:businessToday(),supplierId:supplier.id,supplier:supplier.name,items:product.name,total:100,paid:20,payments:[{id:'initial',method:'Cash',account:'Cash counter',amount:20}],subtotal:100,discount:0,rounding:0,roundingRule:'No rounding',cartSnapshot:[line],inventoryLines:[{productId:product.id,quantity:10,unitCost:10}]});return{name:product.name,unit:product.unit,stock:master.stock,balance:supplier.balance,supplierId:supplier.id,productId:product.id};});
 // Route remount retains in-memory sources; browser refresh deliberately clears preview state.
 await page.goto('http://127.0.0.1:4320/#/app/purchases/new');await page.getByRole('heading',{name:'New purchase',exact:true}).waitFor();await page.goto('http://127.0.0.1:4320/#/app/purchases');
 const action=async(label)=>{await page.getByRole('tab',{name:/^Purchases/}).click();await page.getByRole('button',{name:'Actions for PUR-FRONTEND',exact:true}).click();await page.getByRole('button',{name:label,exact:true}).click();};
 await action('Correct purchase');let dialog=page.getByRole('dialog',{name:'Correct purchase',exact:true});await dialog.getByRole('textbox',{name:'Purchase action reason'}).fill('Correct supplier price');await dialog.getByRole('textbox',{name:'Purchase cost for '+initial.name,exact:true}).fill('11');await dialog.getByRole('button',{name:/Review correction/}).click();const purchaseReview=page.getByRole('dialog',{name:'Review purchase correction',exact:true});await purchaseReview.waitFor();assert.match(await purchaseReview.innerText(),/একশত দশ টাকা মাত্র/);await purchaseReview.getByRole('button',{name:'Confirm correction preview'}).click();assert.match(await dialog.getByRole('region',{name:'Purchase action impact'}).innerText(),/100.*110/);await dialog.getByRole('button',{name:'Confirm purchase preview'}).click();await dialog.waitFor({state:'hidden'});
 await action('Pay due');dialog=page.getByRole('dialog',{name:'Pay purchase due',exact:true});await dialog.getByRole('textbox',{name:'Purchase action reason'}).fill('Evening payment');const amount=dialog.getByRole('textbox',{name:/Paid amount 1/});await amount.fill('200');assert.ok(await dialog.getByRole('button',{name:/Review payment/}).isDisabled());await amount.fill('30');await dialog.getByRole('button',{name:/Review payment/}).click();assert.match(await dialog.getByRole('region',{name:'Purchase action impact'}).innerText(),/90.*60/);await dialog.getByRole('button',{name:'Confirm purchase preview'}).click();await dialog.waitFor({state:'hidden'});
 const returnAction=async()=>{await action('Review return');await page.getByRole('button',{name:'Choose return quantities'}).click();return page.getByRole('dialog',{name:'Return purchase products',exact:true});};
 dialog=await returnAction();await dialog.getByRole('textbox',{name:'Purchase action reason'}).fill('Damaged items');const quantity=dialog.getByRole('textbox',{name:'Quantity for '+initial.name,exact:true});await quantity.fill('11');await dialog.getByRole('button',{name:'Review return',exact:true}).click();assert.match(await dialog.getByRole('alert').innerText(),/remaining/);await quantity.fill('5');assert.ok(await dialog.getByRole('textbox',{name:'Purchase cost for '+initial.name,exact:true}).getAttribute('readonly')!==null);await dialog.getByRole('button',{name:'Review return',exact:true}).click();assert.match(await dialog.getByRole('region',{name:'Purchase action impact'}).innerText(),/55/);await dialog.getByRole('button',{name:'Confirm purchase preview'}).click();await dialog.waitFor({state:'hidden'});
 // Return remaining goods: clear the last due first, then refund the paid balance.
 dialog=await returnAction();await dialog.getByRole('textbox',{name:'Purchase action reason'}).fill('Return remaining items');await dialog.getByRole('textbox',{name:'Quantity for '+initial.name,exact:true}).fill('5');
 const select=dialog.getByRole('combobox',{name:'Return settlement'});await select.click();await page.getByRole('option',{name:'Receive refund',exact:true}).click();await dialog.getByRole('textbox',{name:/Paid amount 1/}).fill('50');await dialog.getByRole('button',{name:'Review return',exact:true}).click();assert.match(await dialog.getByRole('region',{name:'Purchase action impact'}).innerText(),/Refund.*50/);await dialog.getByRole('button',{name:'Confirm purchase preview'}).click();await dialog.waitFor({state:'hidden'});
 await action('Source history');dialog=page.getByRole('dialog',{name:'Purchase source history'});assert.match(await dialog.innerText(),/Correct supplier price.*Evening payment.*Damaged items.*Return remaining items/s);await dialog.getByRole('button',{name:'Close history'}).click();
 const final=await page.evaluate(async({supplierId,productId})=>{const m=await import('/src/data/erpDemoStore.ts');const{purchasePosition}=await import('/src/utils/purchaseSource.ts');const source=m.availablePurchases().find(p=>p.ref==='PUR-FRONTEND');return{stock:m.availableProducts().find(p=>p.id===productId).stock,balance:m.availableParties().find(p=>p.id===supplierId).balance,position:purchasePosition(source,m.availablePurchaseEvents()),events:m.availablePurchaseEvents().length};},initial);
 assert.equal(final.stock,initial.stock);assert.equal(final.balance,initial.balance);assert.equal(final.position.due,0);assert.equal(final.position.credit,0);assert.equal(final.events,4);assert.deepEqual(errors,[]);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await context.close();console.log('Purchase correction, payment, guarded returns, refund and history passed: '+width+'px '+theme);
 }}finally{await browser.close();await server.close();}}
main().catch(e=>{console.error(e);process.exitCode=1;});
